import React, { useEffect, useState } from "react";

function Dashboard() {
  const [resumes, setResumes] = useState([]);
  const [loading, setLoading] = useState(true);

  const token = localStorage.getItem("token");

  useEffect(() => {
    fetchResumes();
  }, []);

  // ============================
  // FETCH RESUMES
  // ============================
  const fetchResumes = async () => {
    try {
      setLoading(true);

      const res = await fetch("http://localhost:5000/api/resume/my", {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      const data = await res.json();

      console.log("📦 Resumes from backend:", data); // 🔥 DEBUG

      setResumes(data);

    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  // ============================
  // DELETE
  // ============================
  const handleDelete = async (id) => {
    try {
      await fetch(`http://localhost:5000/api/resume/${id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      fetchResumes();

    } catch (err) {
      console.error(err);
    }
  };

  // ============================
  // EDIT
  // ============================
  const handleEdit = async (id, oldText) => {
    const newText = prompt("Edit Resume:", oldText);

    if (!newText) return;

    try {
      await fetch(`http://localhost:5000/api/resume/${id}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ text: newText }),
      });

      fetchResumes();

    } catch (err) {
      console.error(err);
    }
  };

  // ============================
  // DOWNLOAD
  // ============================
  const handleDownload = async (text) => {
    try {
      if (!text) {
        alert("No resume content");
        return;
      }

      const res = await fetch("http://localhost:5000/api/resume/download", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ text }),
      });

      if (!res.ok) {
        throw new Error("Download failed");
      }

      const blob = await res.blob();

      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "resume.pdf";
      a.click();

    } catch (err) {
      console.error(err);
      alert("PDF download failed");
    }
  };

  return (
    <div style={styles.page}>
      {/* HEADER */}
      <div style={styles.header}>
        <h1 style={styles.logo}>CareerForge Pro 🚀</h1>

        <div style={styles.actions}>
          <button
            style={styles.primaryBtn}
            onClick={() => (window.location.href = "/")}
          >
            Analyze Resume
          </button>

          <button
            style={styles.logoutBtn}
            onClick={() => {
              localStorage.removeItem("token");
              window.location.href = "/login";
            }}
          >
            Logout
          </button>
        </div>
      </div>

      <h2 style={styles.title}>Your Saved Resumes</h2>

      {loading ? (
        <p>Loading...</p>
      ) : resumes.length === 0 ? (
        <p style={styles.empty}>No resumes found</p>
      ) : (
        <div style={styles.grid}>
          {resumes.map((r) => (
            <div key={r._id} style={styles.card}>
              
              {/* TOP */}
              <div style={styles.cardTop}>
                <span style={styles.score}>
                  ATS: {r.atsScore || 0}
                </span>

                <span style={styles.date}>
                  {r.createdAt
                    ? new Date(r.createdAt).toLocaleDateString()
                    : "N/A"}
                </span>
              </div>

              {/* TEXT */}
              <div style={styles.resume}>
                {r.text && r.text.trim().length > 0
                  ? r.text
                  : "⚠️ No resume content"}
              </div>

              {/* ACTIONS */}
              <div style={styles.cardActions}>
                <button
                  style={styles.editBtn}
                  onClick={() => handleEdit(r._id, r.text)}
                >
                  Edit
                </button>

                <button
                  style={styles.deleteBtn}
                  onClick={() => handleDelete(r._id)}
                >
                  Delete
                </button>

                <button
                  style={styles.downloadBtn}
                  onClick={() => handleDownload(r.text)}
                >
                  Download
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ============================
// STYLES
// ============================
const styles = {
  page: {
    minHeight: "100vh",
    padding: "30px",
    background: "#020617",
    color: "white",
  },
  header: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
  },
  logo: { color: "#38bdf8" },
  actions: { display: "flex", gap: "10px" },
  primaryBtn: {
    background: "#3b82f6",
    padding: "8px 14px",
    border: "none",
    borderRadius: "6px",
    color: "white",
    cursor: "pointer",
  },
  logoutBtn: {
    background: "#ef4444",
    padding: "8px 14px",
    border: "none",
    borderRadius: "6px",
    color: "white",
    cursor: "pointer",
  },
  title: { marginTop: "20px" },
  empty: { opacity: 0.6 },
  grid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(300px, 1fr))",
    gap: "20px",
    marginTop: "20px",
  },
  card: {
    background: "#0f172a",
    padding: "15px",
    borderRadius: "10px",
    border: "1px solid #1e293b",
  },
  cardTop: {
    display: "flex",
    justifyContent: "space-between",
    marginBottom: "10px",
  },
  score: {
    background: "#22c55e",
    padding: "4px 8px",
    borderRadius: "5px",
    fontSize: "12px",
  },
  date: { fontSize: "12px", opacity: 0.7 },
  resume: {
    background: "#020617",
    padding: "10px",
    borderRadius: "6px",
    height: "150px",
    overflow: "auto",
    fontSize: "12px",
    whiteSpace: "pre-wrap",
    marginBottom: "10px",
  },
  cardActions: {
    display: "flex",
    gap: "10px",
    justifyContent: "flex-end",
  },
  editBtn: {
    background: "#3b82f6",
    padding: "6px 12px",
    borderRadius: "6px",
    border: "none",
    color: "white",
    cursor: "pointer",
  },
  deleteBtn: {
    background: "#f59e0b",
    padding: "6px 12px",
    borderRadius: "6px",
    border: "none",
    color: "white",
    cursor: "pointer",
  },
  downloadBtn: {
    background: "#22c55e",
    padding: "6px 12px",
    borderRadius: "6px",
    border: "none",
    color: "white",
    cursor: "pointer",
  },
};

export default Dashboard;
